const canvas = document.querySelector('#world');
const ctx = canvas.getContext('2d');
canvas.width = 1056; canvas.height = 600;
const W=2200,H=1400, player={x:1050,y:680}, keys=new Set();
let seeds=0,wood=0,lanterns=[], target=null, last=0;
// A seeded landscape keeps the grove recognizable on every visit.
let randomSeed=739; function rand(){randomSeed=(randomSeed*16807)%2147483647;return (randomSeed-1)/2147483646}
const trees=[], tufts=[], items=[];
for(let i=0;i<150;i++){let x=rand()*W,y=rand()*H;if(Math.hypot(x-player.x,y-player.y)>125)trees.push({x,y,r:24+rand()*29,t:rand()})}
for(let i=0;i<240;i++)tufts.push({x:rand()*W,y:rand()*H,r:rand()});
for(let i=0;i<42;i++)items.push({x:70+rand()*(W-140),y:70+rand()*(H-140),type:i%2?'wood':'seed',alive:true});
// Place approachable first finds around the opening clearing.
items.push({x:900,y:615,type:'seed',alive:true},{x:1160,y:620,type:'wood',alive:true},{x:1030,y:800,type:'seed',alive:true});
const seedsEl=document.querySelector('#seeds'),woodEl=document.querySelector('#wood'),status=document.querySelector('#status'),build=document.querySelector('#build');
function updateUI(){seedsEl.textContent=seeds;woodEl.textContent=wood;build.disabled=seeds<3||wood<2;status.textContent=build.disabled?'Gather a little more to begin.':'Ready to plant at your feet.'}
function ellipse(x,y,rx,ry,color){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
function draw(time){const camX=Math.max(0,Math.min(W-canvas.width,player.x-canvas.width/2)),camY=Math.max(0,Math.min(H-canvas.height,player.y-canvas.height/2));ctx.clearRect(0,0,canvas.width,canvas.height);ctx.save();ctx.translate(-camX,-camY);ctx.fillStyle='#91ad88';ctx.fillRect(0,0,W,H);
// Broad translucent patches give the ground a hand-painted texture.
for(let i=0;i<tufts.length;i++){const t=tufts[i];ellipse(t.x,t.y,25+t.r*40,9+t.r*13,i%3?'#89a680':'#9bb793');if(i%4===0){ctx.strokeStyle='#769970';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(t.x,t.y);ctx.lineTo(t.x-4,t.y-8);ctx.moveTo(t.x,t.y);ctx.lineTo(t.x+5,t.y-10);ctx.stroke()}}
for(const item of items.filter(i=>i.alive)){if(item.type==='seed'){ellipse(item.x,item.y+6,13,5,'#7d9c78');ellipse(item.x,item.y,8,8,'#f4d383');ellipse(item.x,item.y,3,3,'#fff1be');ctx.fillStyle='#fff1c2';ctx.font='15px serif';ctx.fillText('✧',item.x+9,item.y-7)}else{ellipse(item.x,item.y+6,17,5,'#7d9c78');ctx.strokeStyle='#b97d4d';ctx.lineWidth=7;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(item.x-10,item.y+2);ctx.lineTo(item.x+11,item.y-5);ctx.stroke()}}
const objects=[...trees.map(o=>({...o,kind:'tree'})),...lanterns.map(o=>({...o,kind:'lantern'})),{...player,kind:'player'}].sort((a,b)=>a.y-b.y);
for(const o of objects){if(o.kind==='tree'){ellipse(o.x,o.y+11,o.r*1.15,o.r*.38,'#779775');ctx.fillStyle='#795f47';ctx.fillRect(o.x-5,o.y-15,10,25);ellipse(o.x,o.y-o.r*.65,o.r,o.r*.76,o.t>.5?'#4f795b':'#5d8664');ellipse(o.x-o.r*.22,o.y-o.r*.88,o.r*.68,o.r*.52,o.t>.5?'#608c69':'#6e9873');ellipse(o.x-o.r*.34,o.y-o.r*1.05,o.r*.25,o.r*.15,'#81a67f')}else if(o.kind==='lantern'){ellipse(o.x,o.y+8,19,7,'#789771');const g=ctx.createRadialGradient(o.x,o.y-23,1,o.x,o.y-23,65);g.addColorStop(0,'#ffe8a8aa');g.addColorStop(1,'#ffe8a800');ctx.fillStyle=g;ctx.fillRect(o.x-65,o.y-88,130,130);ctx.strokeStyle='#745b43';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(o.x,o.y);ctx.lineTo(o.x,o.y-28);ctx.stroke();ellipse(o.x,o.y-31,9,10,'#f8d685');ellipse(o.x,o.y-33,5,6,'#fff0b5')}else{ellipse(o.x,o.y+13,18,7,'#668b69');ellipse(o.x,o.y+2,13,15,'#e7d6b1');ellipse(o.x,o.y-12,10,10,'#f4d9b4');ellipse(o.x,o.y-16,12,7,'#604d40');ctx.fillStyle='#e0a968';ctx.fillRect(o.x-10,o.y+1,20,8)}}
ctx.restore();requestAnimationFrame(frame)}
function frame(time){const dt=Math.min((time-last)/1000,.04)||0;last=time;let dx=(keys.has('ArrowRight')||keys.has('d')?1:0)-(keys.has('ArrowLeft')||keys.has('a')?1:0),dy=(keys.has('ArrowDown')||keys.has('s')?1:0)-(keys.has('ArrowUp')||keys.has('w')?1:0);if(dx||dy)target=null;else if(target){dx=target.x-player.x;dy=target.y-player.y;if(Math.hypot(dx,dy)<4){target=null;dx=dy=0}}let len=Math.hypot(dx,dy);if(len){player.x=Math.max(20,Math.min(W-20,player.x+dx/len*170*dt));player.y=Math.max(20,Math.min(H-20,player.y+dy/len*170*dt))}for(const item of items){if(item.alive&&Math.hypot(player.x-item.x,player.y-item.y)<25){item.alive=false;if(item.type==='seed')seeds++;else wood++;updateUI()}}draw(time)}
addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d'].includes(e.key)){keys.add(e.key);e.preventDefault()}});addEventListener('keyup',e=>keys.delete(e.key));canvas.addEventListener('pointerdown',e=>{const rect=canvas.getBoundingClientRect();const camX=Math.max(0,Math.min(W-canvas.width,player.x-canvas.width/2)),camY=Math.max(0,Math.min(H-canvas.height,player.y-canvas.height/2));target={x:camX+(e.clientX-rect.left)*canvas.width/rect.width,y:camY+(e.clientY-rect.top)*canvas.height/rect.height}});build.addEventListener('click',()=>{if(seeds>=3&&wood>=2){seeds-=3;wood-=2;lanterns.push({x:player.x+25,y:player.y});updateUI();status.textContent='A new light in the grove.'}});updateUI();requestAnimationFrame(frame);
